import json
import pathlib
from app.contracts import OrderRecord


def load_local_env(root: pathlib.Path) -> dict[str, str]:
    env_map: dict[str, str] = {}
    env_file = root / ".env"
    if env_file.is_file():
        for raw in env_file.read_text(encoding="utf-8").splitlines():
            line = raw.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                env_map[k.strip()] = v.strip()
    return env_map


def shared_deps_ready(root: pathlib.Path) -> bool:
    marker = root / ".venv_shared" / "site_packages_marker.json"
    if not marker.is_file():
        return False
    data = json.loads(marker.read_text(encoding="utf-8"))
    return bool(data.get("ready"))


def export_orders_csv(orders: list[OrderRecord], delimiter: str = ",") -> str:
    lines = [delimiter.join(["order_id", "amount_cents", "status"])]
    for row in orders:
        lines.append(delimiter.join([row.order_id, str(row.amount_cents), row.status]))
    return "\n".join(lines)

