def paginate(items: list, page: int, page_size: int, max_size: int = 100) -> list:
    if page < 1 or page_size < 1:
        raise ValueError("page and page_size must be >= 1")
    effective_size = min(page_size, max_size)
    start = (page - 1) * effective_size
    if start >= len(items):
        return []
    return items[start : start + effective_size]
